) ENGINE=InnoDB AUTO_INCREMENT=25961 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Histórico granular de Win Rate por Herói/Rank/Mapa';
